-- Independent, checked-in semantic ABI for the privileged RLS runtime.
-- body_md5 is md5(btrim(pg_proc.prosrc, E' \t\n\r')).
CREATE TEMP TABLE steward_expected_rls_functions (
  identity text PRIMARY KEY,
  result text NOT NULL,
  language text NOT NULL,
  volatility "char" NOT NULL,
  parallelism "char" NOT NULL,
  security_definer boolean NOT NULL,
  settings text NOT NULL,
  owner_kind text NOT NULL CHECK (owner_kind IN ('migration', 'bootstrap')),
  body_md5 text NOT NULL,
  app_execute boolean NOT NULL,
  platform_execute boolean NOT NULL
) ON COMMIT DROP;

